{"command":"python3 -c "
from rdflib.plugins.sparql import prepareQuery
test = '''PREFIX wd: <http://www.wikidata.org/entity/>
SELECT ?item
WHERE {
  VALUES ?type { wd:Q35416 wd:Q14098 }
  ?item wdt:P31 ?type .
}
'''
# add wdt prefix
test = test.replace('PREFIX wd:', 'PREFIX wd: <http://www.wikidata.org/entity/>\nPREFIX wdt: <http://www.wikidata.org/prop/direct/>')
print(prepareQuery(test))
""}

